#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>

struct Point { double x, y; };

std::vector<Point> read_simplified(const std::string& filename) {
    std::ifstream f(filename);
    std::vector<Point> result;
    if (!f) return result;
    int n;
    f >> n;
    result.reserve(n);
    for (int i = 0; i < n; i++) {
        Point p;
        f >> p.x >> p.y;
        result.push_back(p);
    }
    return result;
}

int main() {
    auto truth = read_simplified("data/taxi_simplified/6/truth.txt");
    auto old = read_simplified("data/taxi_simplified/6/simplify_old.txt");
    auto sh = read_simplified("data/taxi_simplified/6/SH.txt");

    std::cout << "truth: " << truth.size() << " points\n";
    std::cout << "old: " << old.size() << " points\n";
    std::cout << "sh: " << sh.size() << " points\n";

    // Compare truth vs old
    int first_diff = -1;
    for (int i = 0; i < std::min(truth.size(), old.size()); i++) {
        double dx = truth[i].x - old[i].x;
        double dy = truth[i].y - old[i].y;
        double dist = std::sqrt(dx*dx + dy*dy);
        if (dist > 1e-6) {
            if (first_diff < 0) first_diff = i;
        }
    }
    std::cout << "\ntruth vs old: first diff at index " << first_diff;
    if (first_diff >= 0) {
        std::cout << ":\n  truth: (" << truth[first_diff].x << ", " << truth[first_diff].y << ")\n";
        std::cout << "  old:   (" << old[first_diff].x << ", " << old[first_diff].y << ")\n";
    }

    // Compare truth vs sh
    first_diff = -1;
    for (int i = 0; i < std::min(truth.size(), sh.size()); i++) {
        double dx = truth[i].x - sh[i].x;
        double dy = truth[i].y - sh[i].y;
        double dist = std::sqrt(dx*dx + dy*dy);
        if (dist > 1e-6) {
            if (first_diff < 0) first_diff = i;
        }
    }
    std::cout << "\ntruth vs sh: first diff at index " << first_diff;
    if (first_diff >= 0 && first_diff < (int)sh.size()) {
        std::cout << ":\n  truth: (" << truth[first_diff].x << ", " << truth[first_diff].y << ")\n";
        std::cout << "  sh:    (" << sh[first_diff].x << ", " << sh[first_diff].y << ")\n";
    }

    // Compare old vs sh
    first_diff = -1;
    for (int i = 0; i < std::min(old.size(), sh.size()); i++) {
        double dx = old[i].x - sh[i].x;
        double dy = old[i].y - sh[i].y;
        double dist = std::sqrt(dx*dx + dy*dy);
        if (dist > 1e-6) {
            if (first_diff < 0) first_diff = i;
        }
    }
    std::cout << "\nold vs sh: first diff at index " << first_diff;
    if (first_diff >= 0 && first_diff < (int)sh.size()) {
        std::cout << ":\n  old: (" << old[first_diff].x << ", " << old[first_diff].y << ")\n";
        std::cout << "  sh:  (" << sh[first_diff].x << ", " << sh[first_diff].y << ")\n";
    }

    return 0;
}
