    std::vector<std::vector<Point>> result;
    if (!f) return result;
    int n;
    f >> n;
    result.reserve(n);
    for (int i = 0; i < n; i++) {
        int m;
        f >> m;
        std::vector<Point> poly;
        poly.reserve(m);
        for (int j = 0; j < m; j++) {
            Point p;
            f >> p.x >> p.y;
            poly.push_back(p);
        }
        result.push_back(poly);
    }
    return result;
}

