#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>

struct Point { double x, y; };

std::vector<Point> read_simplified(const std::string& filename) {
    std::ifstream f(filename);
    std::vector<Point> result;
    if (!f) return result;
    int n;
    f >> n;
    result.reserve(n);
    for (int i = 0; i < n; i++) {
        Point p;
        f >> p.x >> p.y;
        result.push_back(p);
    }
    return result;
}

int main() {
    auto truth = read_simplified("data/taxi_simplified/6/truth.txt");
    auto old = read_simplified("data/taxi_simplified/6/simplify_old.txt");
    auto opencv = read_simplified("data/taxi_simplified/6/simplify_opencv.txt");
    auto boost = read_simplified("data/taxi_simplified/6/simplify_boost.txt");
    auto sh = read_simplified("data/taxi_simplified/6/simplify_SH.txt");

    std::cout << "truth: " << truth.size() << " points\n";
    std::cout << "old: " << old.size() << " points\n";
    std::cout << "opencv: " << opencv.size() << " points\n";
    std::cout << "boost: " << boost.size() << " points\n";
    std::cout << "sh: " << sh.size() << " points\n\n";

    auto compare = [&](const std::string& name, const std::vector<Point>& a, const std::vector<Point>& b) {
        int first_diff = -1;
        for (int i = 0; i < std::min(a.size(), b.size()); i++) {
            double dx = a[i].x - b[i].x;
            double dy = a[i].y - b[i].y;
            double dist = std::sqrt(dx*dx + dy*dy);
            if (dist > 1e-6) {
                if (first_diff < 0) first_diff = i;
            }
        }
        std::cout << name << ": first diff at index " << first_diff;
        if (first_diff >= 0) {
            std::cout << "\n  A: (" << a[first_diff].x << ", " << a[first_diff].y << ")";
            std::cout << "\n  B: (" << b[first_diff].x << ", " << b[first_diff].y << ")\n";
        } else {
            std::cout << " - identical!\n";
        }
    };

    compare("truth vs old", truth, old);
    compare("truth vs opencv", truth, opencv);
    compare("truth vs boost", truth, boost);
    compare("truth vs sh", truth, sh);
    std::cout << "\n";
    compare("old vs opencv", old, opencv);
    compare("old vs boost", old, boost);
    compare("old vs sh", old, sh);
    std::cout << "\n";
    compare("opencv vs boost", opencv, boost);
    compare("opencv vs sh", opencv, sh);
    compare("boost vs sh", boost, sh);

    return 0;
}
