#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>

struct Point { double x, y; };

std::vector<std::vector<Point>> read_F_file(const std::string& filename) {
    std::ifstream f(filename);
    std::vector<std::vector<Point>> result;
    if (!f) return result;
    int n;
    f >> n;
    result.reserve(n);
    for (int i = 0; i < n; i++) {
        int m;
        f >> m;
        std::vector<Point> poly;
        poly.reserve(m);
        for (int j = 0; j < m; j++) {
            Point p;
            f >> p.x >> p.y;
            poly.push_back(p);
        }
        result.push_back(poly);
    }
    return result;
}

double polygon_area(const std::vector<Point>& poly) {
    double area = 0;
    for (size_t i = 0; i < poly.size(); i++) {
        size_t j = (i + 1) % poly.size();
        area += poly[i].x * poly[j].y;
        area -= poly[j].x * poly[i].y;
    }
    return std::abs(area) / 2.0;
}

int main() {
    auto F_old = read_F_file("data/taxi_simplified/6/simplify_old_F.txt");
    auto F_sh = read_F_file("data/taxi_simplified/6/simplify_SH_F.txt");
    auto G_old = read_F_file("data/taxi_simplified/6/simplify_old_G.txt");
    auto G_sh = read_F_file("data/taxi_simplified/6/simplify_SH_G.txt");

    // Since F and G are the same, we can check which iterations have intersections
    // An iteration has intersections if the F[i] != full_bbox (4 vertices)

    // Count how many non-trivial F polygons there are before simplification
    // and how many iterations had at least one intersection

    int first_nontrivial_F_old = -1, first_nontrivial_F_sh = -1;
    for (int i = 0; i < std::min(F_old.size(), F_sh.size()); i++) {
        if (F_old[i].size() > 4 && first_nontrivial_F_old < 0)
            first_nontrivial_F_old = i;
        if (F_sh[i].size() > 4 && first_nontrivial_F_sh < 0)
            first_nontrivial_F_sh = i;
    }

    std::cout << "First non-trivial F (size > 4):\n";
    std::cout << "  old: index " << first_nontrivial_F_old << "\n";
    std::cout << "  sh: index " << first_nontrivial_F_sh << "\n\n";

    // The key question: at which iteration does old produce a different simplified point than sh?
    // Let's read the simplified outputs

    auto read_simp = [](const std::string& f) {
        std::vector<Point> pts;
        std::ifstream in(f);
        if (!in) return pts;
        int n; in >> n;
        pts.reserve(n);
        for (int i = 0; i < n; i++) {
            Point p; in >> p.x >> p.y;
            pts.push_back(p);
        }
        return pts;
    };

    auto simp_old = read_simp("data/taxi_simplified/6/simplify_old.txt");
    auto simp_sh = read_simp("data/taxi_simplified/6/simplify_SH.txt");

    std::cout << "Simplified point counts: old=" << simp_old.size() << ", sh=" << simp_sh.size() << "\n\n";

    // Find first divergent point
    for (int i = 0; i < std::min(simp_old.size(), simp_sh.size()); i++) {
        double dx = simp_old[i].x - simp_sh[i].x;
        double dy = simp_old[i].y - simp_sh[i].y;
        double dist = std::sqrt(dx*dx + dy*dy);
        if (dist > 1e-6) {
            std::cout << "First divergent simplified point at index " << i << ":\n";
            std::cout << "  old: (" << simp_old[i].x << ", " << simp_old[i].y << ")\n";
            std::cout << "  sh:  (" << simp_sh[i].x << ", " << simp_sh[i].y << ")\n";

            // This corresponds to iteration i in the algorithm
            // Each iteration produces 2 simplified points
            // So iteration i/2 (integer division) is where it diverged
            int iteration = i / 2;
            std::cout << "\nThis is from iteration " << iteration << " in the algorithm.\n";

            // Find the F[i] for that iteration
            // Actually, we need to map simplified point index back to F/G polygon index
            // This is tricky because we don't have the mapping directly

            break;
        }
    }

    return 0;
}
