    // Test with two overlapping polygons that produce a non-trivial intersection
    std::vector<Point> poly1 = {
        Point(-7000, 0), Point(10000, 0), Point(10000, 10000), Point(-7000, 10000)
    };
    std::vector<Point> poly2 = {
        Point(-10000, 100), Point(0, 100), Point(0, 10000), Point(-10000, 10000)
    };

    Polygon P(poly1.begin(), poly1.end());
    Polygon Q(poly2.begin(), poly2.end());

    std::cout << std::setprecision(10);
    std::cout << "P: " << P.size() << " vertices\n";
    std::cout << "Q: " << Q.size() << " vertices\n";

    // CGAL intersection
    std::vector<Polygon_with_holes> cgal_result;
    CGAL::intersection(P, Q, std::back_inserter(cgal_result));

    std::cout << "\nCGAL intersection:\n";
    if (cgal_result.empty()) {
        std::cout << "  No intersection\n";
    } else {
        const auto& outer = cgal_result[0].outer_boundary();
        std::cout << "  " << outer.size() << " vertices, area=" << CGAL::to_double(outer.area()) << "\n";
        std::cout << "  First vertex (what simplify_old uses): ("
                  << CGAL::to_double(outer.vertices_begin()->x()) << ", "
                  << CGAL::to_double(outer.vertices_begin()->y()) << ")\n";
        std::cout << "  All vertices:\n";
        for (auto it = outer.vertices_begin(); it != outer.vertices_end(); ++it) {
            std::cout << "    (" << CGAL::to_double(it->x()) << ", " << CGAL::to_double(it->y()) << ")\n";
        }
    }

    // SH custom intersection
    auto sh_result = sh_intersection(P, Q);
    std::cout << "\nSH intersection:\n";
    if (sh_result.empty()) {
        std::cout << "  No intersection\n";
    } else {
        std::cout << "  " << sh_result.size() << " vertices\n";
        std::cout << "  First vertex (what simplify_SH uses): ("
                  << CGAL::to_double(sh_result[0].x()) << ", "
                  << CGAL::to_double(sh_result[0].y()) << ")\n";
