        for (const auto& p : sh_result) {
            std::cout << "    (" << CGAL::to_double(p.x()) << ", " << CGAL::to_double(p.y()) << ")\n";
        }
    }

    // Create SH polygon to check area and orientation
    Polygon sh_poly(sh_result.begin(), sh_result.end());
    std::cout << "\nSH polygon as CGAL:\n";
    std::cout << "  Simple: " << (sh_poly.is_simple() ? "yes" : "no") << "\n";
    std::cout << "  CCW: " << (sh_poly.is_counterclockwise_oriented() ? "yes" : "no") << "\n";
