static void intersect_boost(const Polygon& A, const Polygon& B,
                           std::back_insert_iterator<std::vector<Polygon_with_holes>> result) {
    BoostPolygon bA = to_boost_polygon(A);
    BoostPolygon bB = to_boost_polygon(B);
    std::vector<BoostPolygon> out;
    bg::intersection(bA, bB, out);
    for (const auto& bp : out) {
        Polygon p = from_boost_polygon(bp);
        if (p.is_simple() && !p.is_clockwise_oriented()) {
            *result++ = Polygon_with_holes(p);
        }
    }
}

// Helper: find lexicographically smallest vertex (by x, then y)
static Point find_lex_smallest_vertex(const Polygon_with_holes& pwh) {
    const auto& outer = pwh.outer_boundary();
    auto it = outer.vertices_begin();
    Point best = *it;
    for (++it; it != outer.vertices_end(); ++it) {
        double bx = CGAL::to_double(best.x()), by = CGAL::to_double(best.y());
        double ix = CGAL::to_double(it->x()), iy = CGAL::to_double(it->y());
        if (ix < bx || (ix == bx && iy < by)) {
            best = *it;
        }
    }
    return best;
}

