#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>

struct Point { double x, y; };

std::vector<Point> read_simplified(const std::string& filename) {
    std::ifstream f(filename);
    std::vector<Point> result;
    if (!f) return result;
    int n;
    f >> n;
    result.reserve(n);
    for (int i = 0; i < n; i++) {
        Point p;
        f >> p.x >> p.y;
        result.push_back(p);
    }
    return result;
}

