    auto truth = read_simplified("data/taxi_simplified/6/truth.txt");
    auto cgal = read_simplified("data/taxi_simplified/6/simplify_cgal.txt");
    auto opencv = read_simplified("data/taxi_simplified/6/simplify_opencv.txt");
    auto boost = read_simplified("data/taxi_simplified/6/simplify_boost.txt");
    auto sh = read_simplified("data/taxi_simplified/6/simplify_SH.txt");

    std::cout << "truth: " << truth.size() << " points\n";
    std::cout << "cgal: " << cgal.size() << " points\n";
