// Timing instrumentation
struct Timer {
    std::chrono::high_resolution_clock::time_point start;
    const char* name;
    Timer(const char* n) : name(n) { start = std::chrono::high_resolution_clock::now(); }
    ~Timer() {
        auto end = std::chrono::high_resolution_clock::now();
        auto dur = std::chrono::duration<double, std::milli>(end - start).count();
        g_timing[name] += dur;
        g_counters[name]++;
    }
};

inline std::map<std::string, double>& get_timing_map() {
    static std::map<std::string, double> timing;
    return timing;
}
inline std::map<std::string, long long>& get_counter_map() {
    static std::map<std::string, long long> counters;
    return counters;
}

#define TIMER(name) Timer _timer(name)
#define INC_COUNTER(name) get_counter_map()[name]++

void print_timing_summary() {
    auto& timing = get_timing_map();
    auto& counters = get_counter_map();

    if (timing.empty()) return;

    // Sort by time descending
    std::vector<std::pair<std::string, double>> sorted;
    for (const auto& kv : timing) sorted.emplace_back(kv);
    std::sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) {
        return a.second > b.second;
    });

    double total = 0;
    for (const auto& kv : sorted) total += kv.second;

    std::cout << "\n========== TIMING SUMMARY ==========\n";
    std::cout << std::left << std::setw(40) << "Operation" 
              << std::right << std::setw(12) << "Time (ms)" 
              << std::setw(12) << "Calls" 
              << std::setw(10) << "% Total" << "\n";
    std::cout << std::string(74, '-') << "\n";

    for (const auto& kv : sorted) {
        const std::string& name = kv.first;
        double t = kv.second;
        long long c = counters[name];
        double pct = 100.0 * t / total;
        std::cout << std::left << std::setw(40) << name 
                  << std::right << std::setw(12) << std::fixed << std::setprecision(2) << t
                  << std::setw(12) << c
                  << std::setw(10) << std::fixed << std::setprecision(1) << pct << "%\n";
    }
    std::cout << std::string(74, '-') << "\n";
    std::cout << std::left << std::setw(40) << "TOTAL" 
              << std::right << std::setw(12) << std::fixed << std::setprecision(2) << total << "\n";
    std::cout << "====================================\n";
}

