def frechet(orig_path: Path, simp_path: Path, timeout=120) -> Tuple[Optional[float], float]:
    """Compute Frechet distance via Julia frechet_jl script.

    The Julia script expects ID and looks for files in data/taxi_simplified/<id>/.
    """
    t0 = time.monotonic()

    # Extract ID from path like data/1/original.txt -> 1
    # Or handle both data/1 and data/taxi_simplified/1 paths
    orig_str = str(orig_path)
    simp_str = str(simp_path)

    if 'taxi_simplified' in orig_str:
        # Already in taxi_simplified, extract ID
        id_match = [p for p in orig_path.parts if p.isdigit()]
        if id_match:
            traj_id = id_match[-1]
        else:
            return None, time.monotonic() - t0
    else:
        # In data/<id>/original.txt, extract ID
        id_match = [p for p in orig_path.parts if p.isdigit()]
        if id_match:
            traj_id = id_match[-1]
        else:
            return None, time.monotonic() - t0

    cmd = [JULIA_BIN, str(FRECHET_JL), str(traj_id), "--path", simp_str, "--raw"]
    ok, stdout, stderr = run_cmd(cmd, cwd=REPO_ROOT, timeout=timeout)
    elapsed = time.monotonic() - t0
    if not ok:
        return None, elapsed
    try:
        return float(stdout.strip()), elapsed
    except ValueError:
        return None, elapsed

